//! The QR encoder against reference matrices from two independent implementations.
//!
//! `fixtures/qr_reference.json` was produced with `qrcode` 1.5.4 for Node — the library the
//! TypeScript application uses — with the default mask selection, so it also exercises the
//! version, mode and mask choice. `fixtures/qr_cross_check.json` was produced with
//! `python-qrcode` from PyPI at the same version, level and mask, which makes the two files
//! agree module for module on every vector they share. Neither fixture was generated by this
//! encoder; the tests only reproduce their matrices.

use serde_json::Value;
use socdof_core::barcode::qr::{qr, EcLevel, Mode};

const PRIMARY: &str = include_str!("fixtures/qr_reference.json");
const CROSS_CHECK: &str = include_str!("fixtures/qr_cross_check.json");

fn vectors(fixture: &str) -> Vec<Value> {
    let parsed: Value = serde_json::from_str(fixture).expect("fixture is valid JSON");
    parsed["vectors"]
        .as_array()
        .expect("fixture has a vectors array")
        .clone()
}

fn level(vector: &Value) -> EcLevel {
    EcLevel::from_label(vector["ec"].as_str().expect("level")).expect("known level")
}

fn rows(vector: &Value) -> Vec<String> {
    vector["rows"]
        .as_array()
        .expect("rows")
        .iter()
        .map(|row| row.as_str().expect("row is a string").to_string())
        .collect()
}

fn mode(name: &str) -> Mode {
    match name {
        "Numeric" => Mode::Numeric,
        "Alphanumeric" => Mode::Alphanumeric,
        "Byte" => Mode::Byte,
        other => panic!("unknown mode {other}"),
    }
}

#[test]
fn matrices_match_the_typescript_encoder() {
    let vectors = vectors(PRIMARY);
    assert!(vectors.len() >= 15, "the fixture keeps a broad vector set");

    let mut versions = std::collections::BTreeSet::new();
    let mut levels = std::collections::BTreeSet::new();
    let mut modes = std::collections::BTreeSet::new();

    for vector in &vectors {
        let name = vector["name"].as_str().expect("name");
        let text = vector["text"].as_str().expect("text");
        let code = qr(text, level(vector)).unwrap_or_else(|error| panic!("{name}: {error}"));

        assert_eq!(
            code.version(),
            vector["version"].as_u64().expect("version") as u8,
            "{name}: version"
        );
        assert_eq!(
            code.size(),
            vector["size"].as_u64().expect("size") as usize,
            "{name}: size"
        );
        assert_eq!(
            code.mode(),
            mode(vector["mode"].as_str().expect("mode")),
            "{name}: mode"
        );
        assert_eq!(
            code.mask(),
            vector["mask"].as_u64().expect("mask") as u8,
            "{name}: chosen mask"
        );
        assert_eq!(code.rows(), rows(vector), "{name}: module matrix");

        versions.insert(code.version());
        levels.insert(format!("{:?}", code.level()));
        modes.insert(format!("{:?}", code.mode()));
    }

    assert!(
        versions.len() >= 10,
        "the fixture spans several versions: {versions:?}"
    );
    assert_eq!(levels.len(), 4, "every error correction level is covered");
    assert_eq!(modes.len(), 3, "every mode is covered");
}

#[test]
fn matrices_match_the_second_encoder() {
    let primary = vectors(PRIMARY);
    let cross = vectors(CROSS_CHECK);
    assert!(cross.len() >= 14);

    let mut compared = 0;
    for vector in &cross {
        let name = vector["name"].as_str().expect("name");
        let reference = primary
            .iter()
            .find(|candidate| candidate["name"].as_str() == Some(name))
            .unwrap_or_else(|| panic!("{name} is also in the primary fixture"));
        let code = qr(reference["text"].as_str().expect("text"), level(reference))
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        assert_eq!(
            code.rows(),
            rows(vector),
            "{name}: matrix from python-qrcode"
        );
        compared += 1;
    }
    assert_eq!(compared, cross.len());
}

#[test]
fn the_two_fixtures_agree_with_each_other() {
    let primary = vectors(PRIMARY);
    for vector in &vectors(CROSS_CHECK) {
        let name = vector["name"].as_str().expect("name");
        let reference = primary
            .iter()
            .find(|candidate| candidate["name"].as_str() == Some(name))
            .expect("shared vector");
        assert_eq!(rows(vector), rows(reference), "{name}: fixtures agree");
    }
}
